import subprocess
import sys
import os

def run_tests():
    result = subprocess.run(
        [sys.executable, "-m", "pytest", "tests.py"],
        capture_output=True,
        text=True
    )
    if result.returncode != 0:
        print("Tests failed!")
        print(result.stderr)
        return False
    return True

def verify_solution():
    test_files = ["tests.py"]
    for file in test_files:
        if not os.path.exists(file):
            print(f"Missing test file: {file}")
            return False
    return True

def main():
    print("Verifying solution...")
    if not verify_solution():
        return 1

    print("Running tests...")
    if not run_tests():
        return 1

    print("Tests passed successfully!")
    return 0

if __name__ == "__main__":
    sys.exit(main())

